from itertools import combinations
n=12
edges=[]; idx={}
for i in range(n):
    for j in range(i+1,n):
        idx[(i,j)]=len(edges); edges.append((i,j))
clauses=[]
for quad in combinations(range(n),4):
    es=[idx[(a,b)] for a,b in combinations(quad,2)]
    # var positive means blue(1). no red K4 -> at least one blue
    clauses.append([e+1 for e in es])
    # no blue K4 -> at least one red
    clauses.append([-(e+1) for e in es])
fixed={7:0,9:0,23:1,27:0,28:0,29:0,33:1,34:0,39:1,40:0,53:0,58:0,63:0}
for e,val in fixed.items():
    clauses.append([e+1 if val==1 else -(e+1)])
print('clauses',len(clauses))
from pysat.solvers import Glucose3, Minisat22, Cadical153
for Solver in [Glucose3, Minisat22, Cadical153]:
    try:
        s=Solver(bootstrap_with=clauses)
        sat=s.solve()
        print(Solver, sat)
        if sat:
            m=s.get_model()
            sol=[1 if m[i]>0 else 0 for i in range(66)]
            print(sol)
            # verify fixed and cliques
            ok=True
            for e,v in fixed.items():
                if sol[e]!=v: print('fixed fail',e); ok=False
            red=[]; blue=[]
            for quad in combinations(range(n),4):
                vals=[sol[idx[(a,b)]] for a,b in combinations(quad,2)]
                if all(v==0 for v in vals): red.append(quad)
                if all(v==1 for v in vals): blue.append(quad)
            print('ok',ok,'red',red[:5],len(red),'blue',blue[:5],len(blue))
            break
    except Exception as e: print('solver err',Solver,e)
